package dev.veltraph.client.chocolate;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ChocolateFactoryTest {
    static BigDecimal n(String v){return new BigDecimal(v);}
    static final Object session=new Object(),menu=new Object(),screen=new Object();
    static ChocolateFactoryProfile.Marker marker(int slot){return new ChocolateFactoryProfile.Marker(slot,"minecraft:paper","Test row",List.of("Profile: local-test"));}
    static ChocolateFactoryProfile profile(){var f=new ChocolateFactoryProfile.Field(marker(0),"Value: ","");return new ChocolateFactoryProfile(1,"local-test","2026-09-30","Private synthetic Factory",marker(0),f,f,f,f,f,List.of(),1000,2000,null,null,null,null,false);}
    static ChocolateFactoryObservation observation(int revision,int level,String balance,String identity){
        var r=new ChocolateFactoryObservation.Row(1,false,"minecraft:paper","Test upgrade",1,List.of(),identity);
        var inv=new ChocolateFactoryObservation.Row(10,true,"minecraft:diamond","Protected",1,List.of(),"protected-components");
        var q=new ChocolateFactoryObservation.Quote("employee",ChocolateFactoryProfile.Kind.EMPLOYEE,1,level,n("100"),identity,Optional.of(n("1")),"Synthetic prospective final rate");
        return new ChocolateFactoryObservation("local-test",session,menu,screen,revision,1000,"Private synthetic Factory",true,true,Map.of(1,r,10,inv),Optional.of(n(balance)),Optional.of(n("10")),Optional.of(n("1000")),Optional.of(n("200")),Optional.of(n("2000")),Map.of("employee",q));
    }
    static class Port implements ChocolateFactoryRuntime.Port {int clicks;ChocolateFactoryObservation observation;ChocolateFactoryRuntime.Delivery delivery=ChocolateFactoryRuntime.Delivery.SENT;public ChocolateFactoryObservation read(ChocolateFactoryProfile p){return observation;}public ChocolateFactoryRuntime.Delivery click(ChocolateFactoryObservation o,int slot){clicks++;return delivery;}}
    @Test void transparentGoalComparisonAccountsForSpending(){var planner=new ChocolateFactoryPlanner();var comparison=planner.walletGoal(observation(1,1,"200","old"),"employee",n("1000"),n("0"));assertEquals(0,n("80").compareTo(comparison.holding().seconds().orElseThrow()));assertTrue(comparison.buying().seconds().orElseThrow().compareTo(n("81.81"))>0);}
    @Test void prestigeBeyondCapacityStaysUnknown(){var p=profile();var plan=new ChocolateFactoryPlanner().plan(p,observation(1,1,"200","old"),1000,n("0"));assertTrue(plan.untilPrestige().seconds().isEmpty());assertEquals(n("80"),plan.untilCapacity().seconds().orElseThrow().stripTrailingZeros().setScale(0));}
    @Test void onceOnlyAndExactReceipt(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);assertTrue(rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("50"),1000));rt.tick(profile(),1000);port.observation=observation(2,2,"105","new");rt.tick(profile(),1500);rt.tick(profile(),1600);assertEquals(1,port.clicks);assertEquals(ChocolateFactoryRuntime.State.ACKNOWLEDGED,rt.state());assertEquals(n("100"),rt.spent());}
    @Test void sameRevisionNeverAcknowledges(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("0"),1000);rt.tick(profile(),1000);port.observation=observation(1,2,"100","new");rt.tick(profile(),1500);assertEquals(ChocolateFactoryRuntime.State.WAITING_RECEIPT,rt.state());rt.tick(profile(),3101);assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());assertFalse(rt.select(profile(),port.observation,"employee",n("1000"),n("0"),3101));assertEquals(1,port.clicks);}
    @Test void protectedInventoryChangeDeniesReceipt(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("0"),1000);rt.tick(profile(),1000);var o=observation(2,2,"100","new");port.observation=new ChocolateFactoryObservation(o.scope(),o.session(),o.menu(),o.screen(),o.revision(),o.observedMillis(),o.title(),true,true,Map.of(1,o.rows().get(1)),o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),o.quotes());rt.tick(profile(),3101);assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());}
    @Test void unknownDeliveryLatchesAndCancelDoesNotRetry(){var port=new Port();port.delivery=ChocolateFactoryRuntime.Delivery.UNKNOWN;var rt=new ChocolateFactoryRuntime(port);rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("0"),1000);rt.tick(profile(),1000);rt.cancel();rt.tick(profile(),1500);assertEquals(1,port.clicks);assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());assertThrows(IllegalStateException.class,()->rt.reconcileUnknown(true));assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());assertEquals(BigDecimal.ZERO,rt.spent());assertEquals(BigDecimal.ZERO,rt.manualDeclaredDebit()); /* Positive inspected manual100 debit is separately covered by ChocolateQueueManualReconciliationTest. */}
    @Test void budgetReserveAndStalenessDeny(){var rt=new ChocolateFactoryRuntime(new Port());assertFalse(rt.select(profile(),observation(1,1,"200","old"),"employee",n("99"),n("0"),1000));assertFalse(rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("101"),1000));assertFalse(rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("0"),2100));}
    @Test void priceParserSupportsCapturedScalesAndRejectsMalformedNumbers(){var field=new ChocolateFactoryProfile.Field(marker(0),"Value: "," Chocolate");assertEquals(Optional.of(n("2000000000")),field.read(Map.of(0,new ChocolateFactoryObservation.Row(0,false,"minecraft:paper","Test row",1,List.of("Profile: local-test","Value: 2,000,000,000 Chocolate"),"full"))));for(var text:List.of("2b","2,00","NaN","-1"))assertTrue(field.read(Map.of(0,new ChocolateFactoryObservation.Row(0,false,"minecraft:paper","Test row",1,List.of("Profile: local-test","Value: "+text+" Chocolate"),"full"))).isEmpty());assertTrue(field.read(Map.of(0,new ChocolateFactoryObservation.Row(0,false,"minecraft:paper","Test row",1,List.of("Profile: local-test","Value: 100 Chocolate","Value: 200 Chocolate"),"full"))).isEmpty());}
    @Test void fullWalletAndUnknownRateRemainExplicit(){assertEquals(Optional.of(BigDecimal.ZERO),ChocolateFactoryPlanner.time(Optional.of(n("100")),Optional.of(n("100")),Optional.empty()).seconds());assertTrue(ChocolateFactoryPlanner.time(Optional.of(n("0")),Optional.of(n("100")),Optional.empty()).seconds().isEmpty());}
    @Test void referenceCatalogDoesNotGrantBinding(){assertFalse(ChocolateFactoryCatalog.menuBindingsVerified());assertTrue(ChocolateFactoryCatalog.storage("II").isEmpty());assertEquals(new BigDecimal("100000000000"),ChocolateFactoryCatalog.storage("VI").orElseThrow());assertEquals(n("3000000"),ChocolateFactoryPlanner.chocobitUpkeep(3).coinsPerSkyBlockYear());}
    @Test void queueRejectsDuplicateFutureLevelsAndBudget(){var rt=new ChocolateFactoryRuntime(new Port());assertFalse(rt.selectQueue(profile(),observation(1,1,"200","old"),List.of("employee","employee"),n("1000"),n("0"),1000));assertFalse(rt.selectQueue(profile(),observation(1,1,"200","old"),List.of("employee"),n("99"),n("0"),1000));}
    @Test void incompleteProfileCannotAuthorizeAction(){assertThrows(IllegalArgumentException.class,()->ChocolateFactoryProfile.decode("{}"));assertThrows(IllegalArgumentException.class,()->ChocolateFactoryProfile.decode(""));}

    static ChocolateFactoryObservation two(ChocolateFactoryObservation o,boolean changed){
        var q=new ChocolateFactoryObservation.Quote("capacity",ChocolateFactoryProfile.Kind.CAPACITY,2,1,n(changed?"101":"100"),changed?"changed-capacity":"capacity-original",Optional.empty(),"No speculative rate delta");
        var quotes=new HashMap<>(o.quotes());quotes.put(q.id(),q);var rows=new HashMap<>(o.rows());rows.put(2,new ChocolateFactoryObservation.Row(2,false,"minecraft:paper","Test capacity",1,List.of(),q.fullIdentity()));
        return new ChocolateFactoryObservation(o.scope(),o.session(),o.menu(),o.screen(),o.revision(),o.observedMillis(),o.title(),o.profileVerified(),o.cursorEmpty(),rows,o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),quotes);
    }
    @Test void multiStepQueueReobservesAndChargesAggregateBudget(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);assertTrue(rt.selectQueue(profile(),two(observation(1,1,"500","old"),false),List.of("employee","capacity"),n("200"),n("100"),1000));rt.tick(profile(),1000);port.observation=two(observation(2,2,"400","new"),false);rt.tick(profile(),1500);assertEquals(ChocolateFactoryRuntime.State.ACKNOWLEDGED,rt.state());assertTrue(rt.advanceQueue(profile(),1500));rt.tick(profile(),1500);assertEquals(2,port.clicks);var o=two(observation(3,2,"300","new"),false);var qs=new HashMap<>(o.quotes());qs.put("capacity",new ChocolateFactoryObservation.Quote("capacity",ChocolateFactoryProfile.Kind.CAPACITY,2,2,n("200"),"capacity-upgraded",Optional.empty(),"No speculative rate delta"));port.observation=new ChocolateFactoryObservation(o.scope(),o.session(),o.menu(),o.screen(),o.revision(),o.observedMillis(),o.title(),true,true,o.rows(),o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),qs);rt.tick(profile(),1900);assertEquals(ChocolateFactoryRuntime.State.ACKNOWLEDGED,rt.state());assertEquals(n("200"),rt.spent());assertFalse(rt.advanceQueue(profile(),1900));}
    @Test void changedQueuedPriceRequiresFreshDeliberateSelection(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);rt.selectQueue(profile(),two(observation(1,1,"500","old"),false),List.of("employee","capacity"),n("1000"),n("0"),1000);rt.tick(profile(),1000);port.observation=two(observation(2,2,"400","new"),true);rt.tick(profile(),1500);assertFalse(rt.advanceQueue(profile(),1500));assertEquals(ChocolateFactoryRuntime.State.DENIED,rt.state());rt.tick(profile(),1600);assertEquals(1,port.clicks);}
    @Test void lowerThanQuotedSpendCannotBecomeReceipt(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("0"),1000);rt.tick(profile(),1000);port.observation=observation(2,2,"10","new");rt.tick(profile(),3101);assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());}
    @Test void worldOrMenuGenerationChangeLatches(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);rt.select(profile(),observation(1,1,"200","old"),"employee",n("100"),n("0"),1000);rt.tick(profile(),1000);var o=observation(2,2,"100","new");port.observation=new ChocolateFactoryObservation(o.scope(),new Object(),o.menu(),o.screen(),o.revision(),o.observedMillis(),o.title(),true,true,o.rows(),o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),o.quotes());rt.tick(profile(),1500);assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());}
    @Test void eachManualConsequentialActionIsRefused(){for(var kind:List.of(ChocolateFactoryProfile.Kind.PRESTIGE,ChocolateFactoryProfile.Kind.FACTION,ChocolateFactoryProfile.Kind.CONSUMABLE,ChocolateFactoryProfile.Kind.CHOCOBIT,ChocolateFactoryProfile.Kind.RABBIT_COLLECTION)){var o=observation(1,1,"500","old");var q=o.quotes().get("employee");var quote=new ChocolateFactoryObservation.Quote(q.id(),kind,q.slot(),q.level(),q.price(),q.fullIdentity(),q.productionDelta(),q.assumption());var altered=new ChocolateFactoryObservation(o.scope(),o.session(),o.menu(),o.screen(),o.revision(),o.observedMillis(),o.title(),true,true,o.rows(),o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),Map.of(q.id(),quote));assertFalse(new ChocolateFactoryRuntime(new Port()).select(profile(),altered,"employee",n("1000"),n("0"),1000));}}
    @Test void nativeDenialSendsOnceAndCannotTurnIntoUnknownRetry(){var port=new Port();port.delivery=ChocolateFactoryRuntime.Delivery.DENIED;var rt=new ChocolateFactoryRuntime(port);rt.select(profile(),observation(1,1,"500","old"),"employee",n("1000"),n("0"),1000);rt.tick(profile(),1000);rt.tick(profile(),1100);assertEquals(1,port.clicks);assertEquals(ChocolateFactoryRuntime.State.DENIED,rt.state());assertEquals(BigDecimal.ZERO,rt.spent());}
    @Test void historyPreservesScopesAndUnknownStateAcrossDecode(){var h=ChocolateFactoryHistory.decode("");var first=new ChocolateFactoryModule.Journal(1,"a","2026-09-30","ACKNOWLEDGED","x","100","100","receipt");var second=new ChocolateFactoryModule.Journal(1,"b","2026-09-30","UNKNOWN","y","200","0","pending");var stored=ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode(h.with(first)).with(second));assertEquals(2,stored.profiles().size());assertTrue(stored.pending());assertThrows(IllegalArgumentException.class,()->ChocolateFactoryHistory.decode("not json"));}
    @Test void invalidMenuMarkerPlayerDuplicatesAreRefused(){var field=new ChocolateFactoryProfile.Field(marker(0),"Value: ","");assertTrue(field.read(Map.of(0,new ChocolateFactoryObservation.Row(0,true,"minecraft:paper","Test row",1,List.of("Profile: local-test","Value: 100"),"full"))).isEmpty());}
    @Test void dynamicNumericNameBindingCannotMatchArbitrarySuffix(){var m=new ChocolateFactoryProfile.Marker(2,"minecraft:paper","Test Lvl 1",List.of("cue"),"Test Lvl ","");assertTrue(m.matches(new ChocolateFactoryObservation.Row(2,false,"minecraft:paper","Test Lvl 2",1,List.of("cue"),"full")));assertFalse(m.matches(new ChocolateFactoryObservation.Row(2,false,"minecraft:paper","Test Lvl 2 Confirm",1,List.of("cue"),"full")));}

    @Test void maxLevelReceiptDoesNotRequireAnotherPurchasableQuote(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);var original=observation(1,1,"200","old");var q=original.quotes().get("employee");var high=new ChocolateFactoryObservation.Quote(q.id(),q.kind(),q.slot(),159,q.price(),q.fullIdentity(),q.productionDelta(),q.assumption());var before=new ChocolateFactoryObservation(original.scope(),original.session(),original.menu(),original.screen(),1,1000,original.title(),true,true,original.rows(),original.balance(),original.production(),original.capacity(),original.prestigeProgress(),original.prestigeGoal(),Map.of(q.id(),high));assertTrue(rt.select(profile(),before,"employee",n("100"),n("0"),1000));rt.tick(profile(),1000);var o=observation(2,160,"100","new");port.observation=new ChocolateFactoryObservation(o.scope(),o.session(),o.menu(),o.screen(),2,1000,o.title(),true,true,o.rows(),o.balance(),o.production(),o.capacity(),o.prestigeProgress(),o.prestigeGoal(),Map.of(),Map.of("employee",new ChocolateFactoryObservation.ResultTarget("employee",q.kind(),q.slot(),160,"new")));rt.tick(profile(),1500);assertEquals(ChocolateFactoryRuntime.State.ACKNOWLEDGED,rt.state());assertEquals(1,port.clicks);}
    @Test void fullQueueReserveIsProtectedBeforeAnyRequest(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);assertFalse(rt.selectQueue(profile(),two(observation(1,1,"250","old"),false),List.of("employee","capacity"),n("200"),n("100"),1000));assertEquals(0,port.clicks);}
    @Test void pendingNextStepRetainsPriorAcknowledgedSpend(){var first=new ChocolateFactoryModule.Journal(1,"a","2026-10-02","ACKNOWLEDGED","employee","100","100","receipt");var next=new ChocolateFactoryModule.Journal(1,"a","2026-10-02","PENDING","capacity","100","100","selected");var text=ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode("").with(first)).with(next);assertTrue(text.contains("ACKNOWLEDGED"),"Advancing queue erased first step receipt");assertTrue(ChocolateFactoryHistory.decode(text).pending());}
    @Test void missingFirstQueueReceiptCannotDispatchSecondOrRetry(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);var before=two(observation(1,1,"500","old"),false);assertTrue(rt.selectQueue(profile(),before,List.of("employee","capacity"),n("200"),n("100"),1000));rt.tick(profile(),1000);port.observation=before;rt.tick(profile(),3101);assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());assertFalse(rt.advanceQueue(profile(),3101));rt.tick(profile(),3200);rt.cancel();assertEquals(1,port.clicks);assertEquals(BigDecimal.ZERO,rt.spent());assertTrue(rt.acknowledgedUpgrades().isEmpty());}
    @Test void cancelSelectedQueueSendsNothingAndCancelWaitingLatches(){var port=new Port();var rt=new ChocolateFactoryRuntime(port);assertTrue(rt.selectQueue(profile(),two(observation(1,1,"500","old"),false),List.of("employee","capacity"),n("200"),n("100"),1000));rt.cancel();rt.tick(profile(),1000);assertEquals(0,port.clicks);assertTrue(rt.selectQueue(profile(),two(observation(1,1,"500","old"),false),List.of("employee","capacity"),n("200"),n("100"),1000));rt.tick(profile(),1000);rt.cancel();rt.tick(profile(),1100);assertEquals(1,port.clicks);assertEquals(ChocolateFactoryRuntime.State.UNKNOWN,rt.state());assertEquals(0,rt.queued());}

    @Test void additiveHistoryReadsOldFormatAndCountsReceiptOnce(){var old=ChocolateFactoryHistory.decode("{\"schema\":1,\"profiles\":{}}");assertTrue(old.receipts().isEmpty());var ack=new ChocolateFactoryModule.Journal(1,"a","2026-10-02","ACKNOWLEDGED","employee","100","100","receipt");var stored=ChocolateFactoryHistory.decode(ChocolateFactoryHistory.decode(old.with(ack,"receipt-one")).with(ack,"receipt-one"));assertEquals(1,stored.receipts().size());assertEquals("100",stored.receipts().getFirst().journal().price());assertFalse(stored.pending());}

}
